/**
 * Primary keys: time-ordered UUIDs generated by the application
 * (TECHNICAL-PLAN §3).
 *
 * Two reasons the plan asks for time-ordered rather than random keys. Index
 * locality: a random v4 key scatters inserts across the whole B-tree, so a
 * busy table keeps dirtying pages all over disk, while a v7 key appends.
 * Deterministic assignment: an importer needs the key before the row exists,
 * so it can wire up references in one pass.
 *
 * This is RFC 9562 version 7: 48 bits of Unix milliseconds, then the version
 * and variant bits, then random. Postgres 17 has no `uuidv7()` of its own, so
 * the generator lives here and the tables carry no database-side default. A
 * row arriving without an id is a bug worth failing on rather than papering
 * over with a random key.
 */
import { randomBytes, randomInt } from "node:crypto";

/**
 * A new time-ordered UUID.
 *
 * Two ids generated inside the same millisecond order randomly against each
 * other. RFC 9562 allows that, and it costs nothing here: ordering matters at
 * the granularity of index pages, not individual rows.
 *
 * `atMilliseconds` states the time to stamp instead of reading the clock, and
 * exists for the performance dataset (P7-T01a). Index locality is the whole
 * reason for a time-ordered key, and a million rows minted in one process all
 * carry one timestamp prefix and land in one region of the B-tree. Production
 * spreads the same rows over months, so a dataset built without this measures
 * a tree the product never has. It takes a parameter rather than growing a
 * second generator beside it, because two implementations of one bit layout
 * is how seeded data stops matching what the product writes.
 */
export function newId(atMilliseconds: number = Date.now()): string {
  const bytes = randomBytes(16);
  const milliseconds = atMilliseconds;

  // The first 48 bits are the timestamp, most significant byte first.
  bytes[0] = Math.floor(milliseconds / 2 ** 40) & 0xff;
  bytes[1] = Math.floor(milliseconds / 2 ** 32) & 0xff;
  bytes[2] = Math.floor(milliseconds / 2 ** 24) & 0xff;
  bytes[3] = Math.floor(milliseconds / 2 ** 16) & 0xff;
  bytes[4] = Math.floor(milliseconds / 2 ** 8) & 0xff;
  bytes[5] = milliseconds & 0xff;

  // Version 7 in the high nibble of byte 6, variant 10 in the top bits of
  // byte 8. Everything else stays random.
  bytes[6] = ((bytes[6] as number) & 0x0f) | 0x70;
  bytes[8] = ((bytes[8] as number) & 0x3f) | 0x80;

  const hex = bytes.toString("hex");
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    hex.slice(12, 16),
    hex.slice(16, 20),
    hex.slice(20, 32),
  ].join("-");
}

/** The millisecond a v7 id was generated at. Used by tests and diagnostics. */
export function idTimestamp(id: string): number {
  return Number.parseInt(id.replace(/-/g, "").slice(0, 12), 16);
}

/**
 * The characters a short identifier is drawn from: base58, the digits and
 * letters without `0`, `O`, `I` and `l`, which read alike. The alphabet KPI
 * links have carried since migration 0026, so every short link has one shape.
 */
export const SHORT_ID_ALPHABET =
  "123456789abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ";

/** How long a short identifier is: 58^10, about 4 × 10^17 per workspace. */
export const SHORT_ID_LENGTH = 10;

/**
 * A new short identifier (TECHNICAL-PLAN §3, docs/design/short-ids.md S2).
 *
 * **One generator, here beside `newId`.** The write path, the KPI create, the
 * performance dataset and data change 0034 all need one, and the data change
 * lives in this package, which cannot import `packages/core`. Two copies of
 * the alphabet would be how a backfilled row stops looking like a written one,
 * the reason `newId` is single too. `packages/core/src/ids/short.ts` adds the
 * collision retry a write uses.
 *
 * `randomInt` rather than `Math.random`: an identifier is not a secret, since
 * access is checked on every read, but a predictable generator is no reason
 * to keep. `randomInt` draws without the modulo bias a byte would carry.
 */
export function newShortId(): string {
  let out = "";
  for (let index = 0; index < SHORT_ID_LENGTH; index += 1) {
    out += SHORT_ID_ALPHABET[randomInt(SHORT_ID_ALPHABET.length)];
  }
  return out;
}
